+                                @if (references.Count > 2)
+                                {
+                                    <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
+                                }
+                            </div>
+                            <div class="form-row">
+                                <div class="form-group">
+                                    <label>Name *</label>
+                                    <input type="text" @bind="references[index].Name" placeholder="Reference name" />
+                                </div>
+                                <div class="form-group">
+                                    <label>Relationship *</label>
+                                    <input type="text" @bind="references[index].Relationship" placeholder="e.g., Former Manager" />
+                                </div>
+                            </div>
+                            <div class="form-row">
+                                <div class="form-group">
+                                    <label>Email *</label>
+                                    <input type="email" @bind="references[index].Email" placeholder="Email address" />
+                                </div>
+                                <div class="form-group">
+                                    <label>Phone *</label>
+                                    <input type="tel" @bind="references[index].Phone" placeholder="Phone number" />
+                                </div>
+                            </div>
+                        </div>
+                    }
+                    @if (references.Count < 3)
+                    {
+                        <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
+                    }
+                    <div class="form-buttons">
+                        <button class="btn-back" @onclick="PrevStep">Back</button>
+                        <button class="btn-next" @onclick="NextStep">Next</button>
+                    </div>
+                </div>
+                break;
+
+            case 3:
+                @* Step 4: Cover Letter *@
+                <div class="step-content">
+                    <h2>Cover Letter</h2>
+                    <div class="form-group">
+                        <label for="coverLetter">Write your cover letter</label>
+                        <textarea id="coverLetter" @bind="coverLetter" @bind:event="oninput" rows="12" placeholder="Tell us why you're a great fit..." maxlength="2000"></textarea>
+                        <div class="char-count @(coverLetter.Length > 1800 ? "warning" : "")">
+                            @coverLetter.Length / 2000 characters
+                        </div>
+                    </div>
+                    <div class="form-buttons">
+                        <button class="btn-back" @onclick="PrevStep">Back</button>
+                        <button class="btn-next" @onclick="NextStep">Next</button>
+                    </div>
+                </div>
+                break;
+
+            case 4:
+                @* Step 5: Review & Submit *@
+                <div class="step-content">
+                    <h2>Review & Submit</h2>
+
+                    <div class="review-section">
+                        <div class="review-header">
+                            <h3>Personal Information</h3>
+                            <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
+                        </div>
+                        <dl>
+                            <dt>Full Name</dt><dd>@fullName</dd>
+                            <dt>Email</dt><dd>@email</dd>
+                            <dt>Phone</dt><dd>@phone</dd>
+                            <dt>Address</dt><dd>@address</dd>
+                        </dl>
+                    </div>
+
+                    <div class="review-section">
+                        <div class="review-header">
+                            <h3>Work History</h3>
+                            <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
+                        </div>
+                        @foreach (var entry in workEntries)
+                        {
+                            <div class="review-entry">
+                                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
+                                <br />
+                                <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
+                                @if (!string.IsNullOrWhiteSpace(entry.Description))
+                                {
+                                    <p>@entry.Description</p>
+                                }
+                            </div>
+                        }
+                    </div>
+
+                    <div class="review-section">
+                        <div class="review-header">
+                            <h3>References</h3>
+                            <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
+                        </div>
+                        @foreach (var reference in references)
+                        {
+                            <div class="review-entry">
+                                <strong>@reference.Name</strong> (@reference.Relationship)
+                                <br />
+                                <span>@reference.Email | @reference.Phone</span>
+                            </div>
+                        }
+                    </div>
+
+                    <div class="review-section">
+                        <div class="review-header">
+                            <h3>Cover Letter</h3>
+                            <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
+                        </div>
+                        <p class="cover-letter-preview">@coverLetter</p>
+                    </div>
+
+                    <div class="form-buttons">
+                        <button class="btn-back" @onclick="PrevStep">Back</button>
+                        <button class="btn-submit" @onclick="SubmitApplication" disabled="@isSubmitting">
+                            @(isSubmitting ? "Submitting..." : "Submit Application")
+                        </button>
+                    </div>
+                </div>
+                break;
+        }
+    }
+    else
+    {
+        @* Submission Confirmation *@
+        <div class="step-content confirmation">
+            <div class="confirmation-icon">&#10003;</div>
+            <h2>Application Submitted!</h2>
+            <p>Thank you for your application. Your application ID is:</p>
+            <div class="application-id">#@applicationId</div>
+            <p>We'll be in touch soon.</p>
+        </div>
+    }
+</div>
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int currentStep = 0;
+    private bool isValidating = false;
+    private bool isSubmitting = false;
+    private bool isSubmitted = false;
+    private int? applicationId;
+    private List<string> errors = new();
+
+    // Step 1: Personal Info
+    private string fullName = "";
+    private string email = "";
+    private string phone = "";
+    private string address = "";
+
+    // Step 2: Work History
+    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
+
+    // Step 3: References
+    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4: Cover Letter
+    private string coverLetter = "";
+
+    private string GetStepClass(int step)
+    {
+        if (step == currentStep) return "active";
+        if (IsStepCompleted(step)) return "completed";
+        return "future";
+    }
+
+    private bool IsStepCompleted(int step)
+    {
+        return step < currentStep;
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step < currentStep)
+        {
+            errors.Clear();
+            currentStep = step;
+        }
+    }
+
+    private async Task NextStep()
+    {
+        errors.Clear();
+
+        if (!ValidateCurrentStep())
+            return;
+
+        if (currentStep == 0)
+        {
+            isValidating = true;
+            var emailValid = await ApplicationService.ValidateEmailAsync(email);
+            isValidating = false;
+
+            if (!emailValid)
+            {
+                errors.Add("Please enter a valid email address.");
+                return;
+            }
+        }
+
+        if (currentStep < StepNames.Length - 1)
+            currentStep++;
+    }
+
+    private void PrevStep()
+    {
+        errors.Clear();
+        if (currentStep > 0)
+            currentStep--;
+    }
+
+    private bool ValidateCurrentStep()
+    {
+        switch (currentStep)
+        {
+            case 0:
+                if (string.IsNullOrWhiteSpace(fullName)) errors.Add("Full name is required.");
+                if (string.IsNullOrWhiteSpace(email)) errors.Add("Email is required.");
+                if (string.IsNullOrWhiteSpace(phone)) errors.Add("Phone is required.");
+                if (string.IsNullOrWhiteSpace(address)) errors.Add("Address is required.");
+                break;
+            case 1:
+                for (int i = 0; i < workEntries.Count; i++)
+                {
+                    var entry = workEntries[i];
+                    if (string.IsNullOrWhiteSpace(entry.Company)) errors.Add($"Position {i + 1}: Company name is required.");
+                    if (string.IsNullOrWhiteSpace(entry.Title)) errors.Add($"Position {i + 1}: Job title is required.");
+                    if (entry.StartDate == default) errors.Add($"Position {i + 1}: Start date is required.");
+                }
+                break;
+            case 2:
+                for (int i = 0; i < references.Count; i++)
+                {
+                    var r = references[i];
+                    if (string.IsNullOrWhiteSpace(r.Name)) errors.Add($"Reference {i + 1}: Name is required.");
+                    if (string.IsNullOrWhiteSpace(r.Relationship)) errors.Add($"Reference {i + 1}: Relationship is required.");
+                    if (string.IsNullOrWhiteSpace(r.Email)) errors.Add($"Reference {i + 1}: Email is required.");
+                    if (string.IsNullOrWhiteSpace(r.Phone)) errors.Add($"Reference {i + 1}: Phone is required.");
+                }
+                break;
+            case 3:
+                if (string.IsNullOrWhiteSpace(coverLetter)) errors.Add("Cover letter is required.");
+                break;
+        }
+
+        return errors.Count == 0;
+    }
+
+    private void AddWorkEntry()
+    {
+        workEntries.Add(new WorkEntryModel());
+    }
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (workEntries.Count > 1)
+            workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (references.Count < 3)
+            references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (references.Count > 2)
+            references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        isSubmitting = true;
+
+        var application = new JobApplication(
+            new PersonalInfo(fullName, email, phone, address),
+            new WorkHistory(workEntries.Select(e => new WorkEntry(
+                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
+            )).ToList()),
+            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+            coverLetter
+        );
+
+        applicationId = await ApplicationService.SubmitApplicationAsync(application);
+        isSubmitting = false;
+        isSubmitted = true;
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+}
